(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fo"] = {"ui":{"skip":"Far til innihaldið","back":"← Aftur til AI-gile","lang.button":"Mál: {name}","lang.dialog":"Vel eitt mál","lang.search":"Leita eftir máli","lang.none":"Einki mál hóvar","lang.notYet":"{name} er ikki umsett enn","theme.aria":"Skift hátt: ljósur, myrkur ella svartur","theme.toLight":"Skift til ljósan hátt","theme.toDark":"Skift til myrkan hátt","theme.toBlack":"Skift til svartan hátt (veruliga svartur, góður fyri OLED-skermar)","words.underline":"Strika undir hesi orðini á síðuni","words.underlineHelp":"Halt músina yvir ella trýst á eitt prikkað orð fyri at síggja, hvat tað merkir.","index.title":"AI-gile: títt AI-menningarlið, á einum borði","index.description":"AI-gile er eitt kanban-borð til AI-kodulið. Tey arbeiða meðan tú sovir; tú fært ein stuttan bunka við tilfarið at taka avgerð um, royna og góðkenna.","hero.logoAlt":"AI-gile borðtekn","hero.h1.html":"Títt AI-menningarlið, á einum&nbsp;borði.","hero.alpha":"🐣 Lukkað pre-alfa","hero.alphaTitle":"Tíðliga og ikki liðugt: takk fyri at royna!","hero.lede":"Tey byggja meðan tú sovir. Tú vaknar til ein stuttan bunka: nøkur spurningar, nøkur at royna, ein ella tveir purpurdiamantir. Klikk, góðkent, aftur til kaffibollan.","dl.windows":"Windows-app","dl.browser":"Brúka í kagarinum","dl.messenger":"📱 Messenger til fartelefonina","dl.soon":"Kemur skjótt","dl.notify":"🔔 Boða mær frá, tá tað letur upp","dl.notifySmall":"Alfa ella beta","hero.secondary":"Agile, men liðið hevur ongantíð brúk fyri standandi-fundar-kaffi. (Tey hava standandi fund kortini.)","pitch.h2":"AI-gile í so nógvum orðum, sum tú vilt","pitch.lede":"Vel eina longd, frá einum orði upp í 144. Hvør longd er sín egni frágreiðing, skrivað til tann stødd. Drag rennuna ella brúka pílarnar.","pitch.rangeLabel":"Longd í orðum","pitch.dice":"🎲 ein onnur útgáva","pitch.words.one":"{n} orð","pitch.words.other":"{n} orð","pitch.letters.one":"{n} bókstavur","pitch.letters.other":"{n} bókstavir","pitch.chars.one":"{n} tekin","pitch.chars.other":"{n} tekin","count.line.html.one":"{n} kort á borðinum júst nú","count.line.html.other":"{n} kort á borðinum júst nú","people.humans.html.one":"👥 {n} menniskja","people.humans.html.other":"👥 {n} menniskjur","people.agents.html.one":"🤖 {n} agentur","people.agents.html.other":"🤖 {n} agentar","people.working.html.one":"⚡ {n} í arbeiði júst nú","people.working.html.other":"⚡ {n} í arbeiði júst nú","pre.title":"AI-gile: her verður nakað bygt","pre.description":"Her verður nakað bygt. Eitt borð, har AI-lið byggja tað, tú biður um, og læra teg á vegnum. Fyribils eitt lukkað pre-alfa við vinum.","pre.h1":"Her verður nakað bygt. 🤫","pre.line":"Eitt borð, har AI-lið byggja tað, tú biður um, og læra teg á vegnum. Fyribils eitt lukkað pre-alfa við vinum.","pre.btn":"🔔 Boða mær frá, tá tað letur upp","pre.peek":"Aftanfyri glasið: veruliga borðið, beinleiðis. Hvørt kort er ein litaður strikur.","pre.peekFake":"Aftanfyri glasið: soleiðis sær eitt borð í arbeiði út.","features.aria":"Hvat tað ger","f.pile.h":"Ein bunki til tín","f.pile.html":"<b>Fyri teg</b> inniheldur alt, sum bíðar eftir tær, í øllum verkætlanum: spurningar, tilfar at royna, uppgávur, sum bara ein maður kann gera. Tín bíðirøð sigur, hvat er næst og hvussu leingi tað tekur.","f.sleep.h":"Lið, sum arbeiða meðan tú sovir","f.sleep.p":"Hvør verkætlan hevur ein leiðara og eitt lið av AI-agentum. Skriva eina viðmerking á eitt kort, og liðið vaknar, ger arbeiðið og gevur tær tað aftur við stigum, sum eisini ein móður maður kann fylgja.","f.tester.h":"Ein AI-royndari kannar fyrst","f.tester.p":"Áðrenn nakað kemur til tín, fylgir ein royndari stigunum í einum avriti av appini og vísir, hvat hann sá, við skíggjamynd. Blaða tú gjøgnum tey, sum eru greidd, og góðkenn við einum klikki.","f.proof.h":"Prógv, ikki lyfti","f.proof.p":"Hvør yvirlatan vísir, hvat broytt er: fílurnar, diff-ið, skíggjamyndirnar. Tú sleppur undan at lata hvørt app upp fyri at sæa, um tað er liðugt.","f.chat.h":"Práta við leiðararnar hjá tær","f.chat.p":"Ein Discord-líknandi rekki: eitt tekn fyri hvørja verkætlan, purpurdiamantir fyri tað, sum hevur brúk fyri tær. Send leiðaranum eitt hugskot; hann ger kort og eina ætlan burturúr, við einum ✅ Go-knappi.","f.tidy.h":"Heldur seg sjálvt rættiliga","f.tidy.p":"Kort, sum hanga saman, renna saman, ruglaðir heitir verða rættaðir, og ein tokenkanning heldur kodu lættari. Færri ting at skifta millum, minni at hugsa um.","f.private.h":"Títt, á tíni teldu","f.private.li1":"Borðið koyrir á tínari egnu maskinu og svarar bara tær.","f.private.li2":"Privatar boð millum fólk eru enda-til-enda krypterað.","f.private.li3":"Eingin konta, ongir fylgjarar, ongar cookies.","f.lang.h":"Á tínum máli","f.lang.p":"Meiri enn 120 mál, frá hollendskum, valisiskum og japanskum til sjóræningamál, Yoda og klingonskt, við skjótum skifti aftur til enskt fyri fakorðini.","f.service.h":"Frá einum hugskoti til eina veruliga tænastu","f.service.p":"Hevur tú bygt okkurt við AI, sum fólk nú nýta? Merk tað sum tænastu, og borðið hjálpir tær at reka tað væl: uppi-tíðar eftirlit, ein almenn støðusíða, hendingar við frágreiðing, broytingar, sum krevja eitt Go, og trygdaravrit, ið verða kannað dagliga. Hjálpin lærir teg hvørt stig, so hvørt tú fert fram.","msgr.h2":"AI-gile Messenger: toymið í lummanum","msgr.p1":"Tosa við AI-toymið uttan at lata borðið upp. Kjatta við verkætlanarleiðararnar og vinirnar, og síggj royndarstigini á einum korti og svara teimum, alt frá fartelefonini.","msgr.p2":"Skanna ein QR-kotu á borðinum fyri at para. Fyrstu ferð? Eitt vinarligt demo-kjatt vísir tær runt.","msgr.when":"Fyrst Android, síðan ein vevútgáva til fartelefonir og iPhone.","msgr.who":"Verkætlanarleiðarin hjá tær","msgr.b1":"Rættingin til myrka háttin er klár. Vilt tú hava royndarstigini?","msgr.b2":"Ja takk!","msgr.b3":"1. Lat Stillingar upp. 2. Vel Myrkt. Sær tað rætt út?","tl.aria":"Tíðarlinja frá fyrsta samrøðu til vegakortið","tl.h2":"Frá fyrstu práti til tað, sum er næst","tl.lede":"Veruligar dagar og tíðir, í tínum egna tíðarsvæði. Aftaná í dag er tað ætlanin, uttan lovaðar dagar.","tl.today":"Í dag","tl.planned":"ætlað","tl.doing":"í gerð","tl.cards.one":"{n} kort","tl.cards.other":"{n} kort","join.h2":"Vertu við","join.lede":"AI-gile verður bygt av einum skeggutum sérlingi við AuDHD og nøkrum stríðum við sálarheilsuna, og av nógvum tolnum agentum. Tað er privat enn, í lukkaðari alfu saman við vinum. Vilt tú royna, tá tað letur upp?","join.btn":"Boða frá áhuga","join.small":"Vit senda tær teldupost, einki annað","footer.tag":"AI-gile. Ongir fylgjarar, ongar cookies, einki standandi-fundar-kaffi.","footer.licence":"Fyritøkuloyvi","footer.status":"Støða","footer.privacy":"Hvat vit goyma","footer.thanks":"Samtalur takk veri ChilledChat","form.sending":"Sendi…","form.failed":"Tað riggaði ikki: royn aftur seinni.","form.offline":"Fekk ikki samband við AI-gile: royn aftur seinni.","form.keep":"Vit brúka hetta bert til at svara tær, síðan strika vit tað. Ongir fylgjarar, ongar cookies.","form.keepLink":"Hvat vit goyma","interest.title":"AI-gile: boða mær frá, tá alfan letur upp","interest.description":"Skriva tín teldupost fyri at frætta, tá lukkaða alfan ella betan hjá AI-gile letur upp.","interest.h1":"🔔 Boða mær frá, tá tað letur upp","interest.lede":"AI-gile er í lukkaðari pre-alfu. Skriva tín teldupost, og vit skriva tær eina ferð, tá pláss er til tín.","interest.email":"Tín teldupostur","interest.which":"Hvør royndin?","interest.alpha":"Lukkað alfa: tíðliga, ruggað, nógvar broytingar","interest.beta":"Beta: støðugari, seinni","interest.both":"Annaðhvørt, hvat so fyrst letur upp","interest.submit":"Set meg á listan","interest.thanks":"Takk! Tú ert á listanum.","licence.title":"AI-gile: fyritøkuloyvi","licence.description":"Brúkar tú AI-gile í tíni fyritøku? Søk um eitt ókeypis fyritøkuloyvi.","licence.h1":"📜 Fyritøkuloyvi","licence.lede":"Brúkar tú AI-gile á arbeiðsplássinum? Sig okkum, hvør tú ert og hvat tú gert. Um tað ger gott, er loyvið ókeypis.","licence.company":"Fyritøka","licence.website":"Heimasíða","licence.what":"Hvat tú gert","licence.how":"Hvussu tað hjálpir heiminum","licence.email":"Teldupostur","licence.submit":"Søk","licence.thanks":"Takk! Vit svara við teldupósti.","status.title":"AI-gile støða","status.h1":"AI-gile støða","status.quiet":"Alt er kvirt","status.intro":"Riggar AI-gile júst nú? Henda síðan kannar heimasíðuna, deiling av talvum, samtalur og niðurtøkuna hvørjar 5 minuttir.","status.up":"Riggar (svaraði eftir {ms} ms)","status.slow":"Svaraði ikki seinastu kanningini, royni aftur","status.down":"Úr gongd: svaraði ikki seinastu tveimum kanningunum","status.svc.web":"Heimasíða","status.svc.web.offers":"Henda síðan: hvat AI-gile er, og áhugaformularin","status.svc.boards":"Deiling av talvum","status.svc.boards.offers":"Almennar talvur, boð millum vinir og innbjóðingar","status.svc.calls":"Samtalur","status.svc.calls.offers":"Rødd, video og skermdeiling í AI-gile","status.svc.download":"Niðurtøka","status.svc.download.offers":"Windows-innleggjarin og innbjóðingarleinkjur","status.checking":"Kanni…","status.offline":"Fái ikki samband við støðutænastuna júst nú (royni aftur)","status.updated":"dagført {ago}","status.justNow":"júst nú","status.min":"{n} min síðani","status.hours":"{n} t síðani","status.days":"{n} d síðani","privacy.title":"AI-gile: hvat vit goyma","privacy.h1":"Hvat vit goyma","privacy.lede":"Stutt sagt: bert tað, tú sendir okkum, og ikki leingi.","privacy.only":"Bert tað, tú sendir okkum: tað, tú skrivar í eitt formular, so sum teldupostin hjá tær. Einki annað um teg.","privacy.sealed":"Tað verður innsiglað, so ambætarin hjá okkum ikki kann lesa tað: í kaganum hjá tær, áðrenn tað fer avstað (á einum eldri kaga, tá ið tað kemur fram). Bert okkara egna talva kann lata tað upp.","privacy.server":"Tað verður strikað av ambætaranum, so skjótt sum tað kemur fram á talvuna hjá okkum. Alt, ið enn liggur har eftir 30 dagar, verður strikað líkavæl.","privacy.board":"Vit goyma tað á talvuni hjá okkum bert, til vit hava svarað tær, síðan strika vit tað har eisini.","privacy.none":"Ongir fylgjarar, ongar cookies, eingin greining.","privacy.local":"Málið hjá tær og valið millum ljóst og myrkt verða verandi í tínum egna kaga. Tey verða ongantíð send til okkara.","privacy.ask":"Vilt tú hava tað burtur fyrr? Svara teldupostinum frá okkum og sig frá.","live.h2":"Sær tað verða bygt, beinleiðis","live.caption":"Hvert kort er fjalt: tú sært skapið á arbeiðinum, ikki orðini.","live.watching.one":"beinleiðis: {n} hyggja","live.watching.other":"beinleiðis: {n} hyggja","live.last.now":"Seinasta kort flutt júst nú","live.last.min.one":"Seinasta kort flutt fyri {n} min síðani","live.last.min.other":"Seinasta kort flutt fyri {n} min síðani","live.last.hour.one":"Seinasta kort flutt fyri {n} tíma síðani","live.last.hour.other":"Seinasta kort flutt fyri {n} tímum síðani","live.last.day.one":"Seinasta kort flutt fyri {n} degi síðani","live.last.day.other":"Seinasta kort flutt fyri {n} døgum síðani","live.offline":"Beinleiðis talvan tekur sær eina løtu at kvíla. Kom aftur skjótt.","live.cols":"Backlog|At gera|Í gerð|Toymið kannar|Fyri teg at testa|Fyri toymið|Liðugt"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotar.","Avgreitt."]},{"n":2,"texts":["Robotar arbeiða.","Agentar, skipaðir.","Hugskot, bygd."]},{"n":3,"texts":["Kanban fyri robotar.","Hugskot verða eyðkenni.","Ókeypis agent-kanban."]},{"n":5,"texts":["Kanban-borð rikið av agentum.","Tú skrivar, agentar byggja.","Ókeypis, lokalt, roynt, eitt sindur tilkomið."]},{"n":8,"texts":["Eitt ókeypis kanban-borð, har AI-agentar arbeiða.","Skriva eitt hugskot. Agentar byggja. Tú góðkennir.","Agile fyri ein mann og nógvar tolnar robotar."]},{"n":13,"texts":["Eitt kanban-borð á tíni teldu, har AI-agentar taka kortini og gera arbeiðið.","Skriva eitt hugskot. Eitt lið av agentum bygger tað. Ein royndari kannar tað.","Ókeypis, eingin konta, ongir fylgjarar: eitt borð, nakrir robotar, og tú ræður."]},{"n":21,"texts":["AI-gile er eitt kanban-borð at arbeiða saman við AI-kodaagentum. Tey taka kortini; tú roynir tey og góðkennir tey.","Hvør verkætlan fær ein leiðara og eitt lið av AI-agentum. Skriva eina viðmerking á hvørt kort, og liðið fer til verka.","Eitt ókeypis, persónligt uppgávuborð, sum koyrir á tíni egnu teldu. Arbeiðararnir eru robotar. Tann, sum sigur ja, ert tú."]},{"n":34,"texts":["Tú leggur hugskot á eitt borð. Eitt lið av AI-agentum ger tey til virkandi eyðkenni, roynir tey og gevur tær tey aftur við stigum at royna. Einki telst sum liðugt, fyrr enn tú sigur tað.","AI-gile er eitt heimagjørt kanban-borð, sum Rich bygdi við nógvari hjálp frá teimum agentum, sum tað nú stýrir. Tað er ókeypis, koyrir á tíni teldu og verður deilt við vinir, ikki selt.","Hugsa tær eitt vanligt kanban-borð, við súlum frá Backlog til Liðugt, nema at kortini verða tikin av AI-agentum. Tey boða frá framgongd, spyrja, tá tey sita fast, og bíða altíð eftir tínari góðkenning."]},{"n":55,"texts":["AI-gile er eitt kanban-borð, har liðið er gjørt av AI-agentum. Hvør verkætlan hevur ein leiðara, sum ætlar arbeiðið, og hjálparar, sum byggja tað. Tá eitt eyðkenni er klárt, roynir ein AI-royndari tað og tekur eina skíggjamynd, síðani kemur tað í tín bunka. Góðkenn tað, ella skriva eina viðmerking, og tey gera tað umaftur.","Tað byrjaði sum háttur hjá einum manni at fylgja við í nógvum AI-kodusessiónum í senn, og vaks til eitt veruligt borð. Tað koyrir á tíni maskinu, krevur onga kontu og hevur ongar fylgjarar. Tað er ókeypis fyri vinir og forvitin. Tað er eisini ikki liðugt, so ríkna við rúgvum kantum og einstaka undran.","Her er sanna útgávan. Tú mást enn hava hugskotini, og tú mást enn kanna úrslitini. Tað, sum AI-gile ger, er alt hitt ímillum: tað heldur kortunum í røð, vekur røttan agent, tá tú skrivar viðmerking, vísir júst hvat broytt er, og leggur alt í ein stuttan bunka til tín."]},{"n":89,"texts":["AI-gile er eitt ókeypis kanban-borð, sum tú letur koyra á tíni egnu teldu. Í staðin fyri fólk hevur hvør verkætlan eitt lið av AI-agentum: ein leiðara, sum ger hugskotini hjá tær til kort og eina ætlan, og hjálparar, sum taka kortini í raðfylgju eftir týdningi. Tá okkurt er bygt, fylgir ein AI-royndari royndarstigunum og vísir tær, hvat hann sá. Síðani bíðar tað í einum bunka, sum eitur Fyri teg. Tú góðkennir tað, ella tú skrivar eina viðmerking, og liðið roynir enn eina ferð. Einki kemur nakrantíð til Liðugt uttan teg.","Nøkur eyðkenni, sum tú kanska ikki væntar. Ein náttarvakt heldur súlini At gera fullari, meðan tú sovir, og velur kort, sum ikki hava brúk fyri svari frá tær. Ein tokentalari vísir, hvussu nógv agentarnir hava brúkt í dag og hesa vikuna, og Eingin token-hátturin sigur teimum at steðga at brúka. Tú kanst senda vinum boð, og privat boð eru enda-til-enda krypterað. Borðið tosar umleið 120 mál, millum annað hollendskt, flamskt, sjóræningamál og klingonskt. Einki av hesum kostar ein oyra, og ongin roynir at selja tær tað.","AI-gile er eitt lítið, persónligt tiltak, ikki ein fyritøka. Rich vildi taka sær av fleiri AI-kodaverkætlanum uttan at lata hvørt app upp fyri at kanna tær, so hann og agentarnir bygdu eitt borð til tað, og brúktu síðani borðið til at byggja restina av sær sjálvum. Tað er í lukkaðari pre-alfu, sum merkir, at tað riggar, mestsum, fyri ein bólk av vinum. Her er eingin prísasíða, einki fregnbræv og ongin vøkstrarætlan. Um tað ljóðar nyttigt, kanst tú biðja um at royna tað, tá tað letur eitt sindur meiri upp."]},{"n":144,"texts":["AI-gile er eitt kanban-borð fyri ein mann og nógvar AI-agentar. Tað koyrir á tíni egnu teldu og er heilt ókeypis. Tú leggur verkætlanir afturat, og hvør verkætlan fær ein leiðara og eitt lítið lið. Tú prátar við leiðaran, eitt sindur sum á Discord, og lýsir eitt hugskot; leiðarin ger kort og eina ætlan burturúr og bíðar síðani eftir, at tú trýstir á Go. Liðið arbeiðir seg gjøgnum kortini í raðfylgju eftir týdningi, við einari einfaldari boðraðlinju gjørdari til málmodellir. Áðrenn nakað kemur aftur til tín, fylgir ein AI-royndari stigunum í einum avriti av appini og leggur eina skíggjamynd við. Liðugt arbeiði kemur í tín bunka við broyttum fílum og diff-inum. Tú góðkennir tað, ella tú letur eina viðmerking eftir, og liðið vaknar og roynir aftur. Bara tú kanst flyta eitt kort til Liðugt.","Ein dagur við AI-gile, umleið. Um kvøldið letur tú nøkur viðmerkingar eftir: hesin knappurin er á skeivum stað, hin listin eigur at vera raðfest, kundi tað eisini fingið myrkan hátt. Tú fert í song. Agentarnir lesa viðmerkingarnar, gera broytingarnar, royna tær og geva tær aftur til tín. Um At gera tæmist, fyllir náttarvaktin tað úr backlog við kortum, sum ikki hava brúk fyri svari frá tær. Um morgunin er ein stuttur bunki: nøkur spurningar og nøkur ting at royna, hvørt við stigum, sum ein søvnugur maður kann fylgja, og skíggjamynd av, at tað riggar. Tú klikkar teg gjøgnum, góðkennir tey góðu og sendir restina aftur. Ein tokentalari vísir, hvat alt hetta brúkti, og Eingin token-hátturin er til tær magru vikurnar. So etur tú morgunmat, sum agentarnir ikki kunnu hjálpa við enn.","Fyrst, hvat AI-gile ikki er. Tað er ikki ein startup, tað er ikki til sølu, og ongin savnar tínar dátur. Tað er eitt ókeypis borð, sum koyrir á tíni teldu, uttan kontur, uttan fylgjarar og uttan cookies. Hvat tað er: ein rættilig støð at sæa allar AI-kodaverkætlanirnar í senn, við einum liði av agentum, sum gera kortini, og tær, sum taka avgerðirnar. Tað rennur kort saman, sum hanga saman, rættar ruglaðar heitir, og hevur eyga við, um kodan verður verandi lætt. Tað tosar umleið 120 mál, frá hollendskum og flamskum til sjóræningamál og klingonskt. Vinir kunnu senda hvønn øðrum boð, privat og krypterað. Tað varð bygt av Rich og nógvum tolnum agentum, mestsum við at brúka seg sjálvt. Tað er í lukkaðari pre-alfu, so tað er ruggað sums staðni. Um tað ljóðar stuttligt, bið vælsiðað, og kanska sleppur tú tíðliga inn."]}],"quips":{"1":"Eitt orð. Djarvt. Kanska ov djarvt.","3":"Trý orð. Longu ærligari enn flestu vøruvevir.","8":"Átta orð. Enn styttri enn ein standandi fundur.","21":"Longdirnar eru annars story points. Sjálvsagt eru tær tað.","55":"Fimmtiofimm orð. Tvey kort vórðu liðug, meðan tú las hetta.","144":"Hetta er tann langa. Ongin 233 er til. Agentarnir eru farnir í song."}},"timeline":{"first-idea.name":"Fyrsta hugskotið","first-idea.line":"Fyrsta samrøða av øllum, áðrenn nøkur koda var til.","first-board.name":"Fyrsta borð","first-board.line":"Eitt borð, sum fylgir sínum egna bygnaði: kort, súlur, drag og slepp, verkætlanir.","team-roles.name":"Lið og leiklutir","team-roles.line":"Agentprofilir, liðsmynstur, rúm og hvør ger hvat.","install.name":"Uppsetan og útgávur","install.line":"Ein zip, sum ein vinur kann seta upp, sjálvdagføring, rásir og afturrulling.","usage-saver.name":"Nýtslusparing","usage-saver.line":"Máta hvat koyringar kosta, halda kodu lættari, spara markið hjá tær.","friends.name":"Vinir og deiling","friends.line":"Privatar boð, ruglað relay, innbjóðingar, leiklutir og deild verkætlanir.","languages.name":"Mál","languages.line":"Hvør skíggjatekstur í einari málfílu, við hollendskum og flamskum fyrst.","ai-tester.name":"AI-royndari","ai-tester.line":"Ein royndari kannar hvørja yvirlatan fyrst og vísir, hvat hann sá.","website.name":"Heimasíðan","website.line":"aigile.lol, teaserin og henda tíðarlinjan.","streaming.name":"Prát og streymur","streaming.line":"Discord, Twitch, OBS, streymarahættur, GIF og emojir.","no-ai.name":"Útgáva uttan AI","no-ai.line":"Eitt borð til tey, sum koda uttan AI, og almenn borð.","night-watch.name":"Náttarvakt","night-watch.line":"Ein vaktari og ein Scrum Master halda liðunum við uppgávuna meðan tú sovir.","p-more.name":"Alt annað","p-more.line":"Smærri hugskot, sum bíða enn eftir síni tøk.","p-android.name":"Telefon og Android","p-android.line":"Kom til borðið hjá tær frá telefonini, síðani eitt upprunaligt Android-app.","p-release.name":"Alfa og longri","p-release.line":"Lukkað alfa, livandi heimasíðan, síðani beta.","p-languages.name":"Fleiri mál","p-languages.line":"130 mál, og ein málsdýpdarstøða til tey, ið læra.","p-engines.name":"Fleiri AI-motorar","p-engines.line":"Vel Claude, Codex, Gemini, Copilot ella Cursor fyri hvønn agent.","p-pro.name":"Fakligur háttur","p-pro.line":"Vandamerki, samanrenningarbørur, hendingarkort og rekkverk.","p-self.name":"Varða um teg","p-self.line":"Móðurhættur, sjálvsrøktaráminningar og 4:20.","p-servers.name":"Ambætarar og vøkstur","p-servers.line":"Almennar ambætaraskipanir, leiklutir og ætlan fyri vøkstri.","p-livestream.name":"Streymiískoyti","p-livestream.line":"Twitch-prát, egnar emojir og eitt almennt beinleiðis sjónarhorn."},"words":{"button":"📖 Fakorð","h":"📖 Orð greitt frá","intro":"Orðini, tú hittir í AI-gile, á einføldum máli: at byggja, at broyta trygt, at halda tí koyrandi fyri tey, ið nýta tað, og at arbeiða sum toymi saman við AI.","search":"Leita eftir einum orði…","none":"Einki orð samsvarar.","close":"Lat aftur","count":{"one":"{count} orð","other":"{count} orð"},"groups":[{"id":"build","name":"🛠️ At byggja"},{"id":"change","name":"🔀 At broyta trygt"},{"id":"run","name":"🛎️ At reka eina tænastu"},{"id":"team","name":"🤝 At arbeiða sum toymi (eisini við AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Mappan hjá verkætlanini við koduni og allari søguni av commits, vanliga eisini goymd á GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Ein sær lina av arbeiði í koduni, so at broytingar kunnu gerast uttan at nerta við høvuðsútgávuna.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Ein goymd mynd av koduni, við einum stuttum notati um, hvat broyttist. Tú kanst altíð fara aftur til eina.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"At senda goymdar myndir (commits) frá hesi teldu upp á GitHub, so at tær eru trygdarviðgjørdar og deildar."},{"id":"merge","g":"build","word":"Merge","text":"At knýta broytingarnar hjá einum branch aftur inn í høvuðsútgávuna."},{"id":"pr","g":"build","word":"Pull request","text":"At biðja um, at broytingarnar hjá einum branch verða kannaðar og knýttar inn í høvuðsútgávuna.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"At rudda koduna uttan at broyta, hvat hon ger: minni fílur, greiðari navn, minni endurtøka."},{"id":"bug","g":"build","word":"Bug","text":"Okkurt, sum ikki riggar, sum tað skal.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"At royna eitt liðugt stykki av arbeiði fyri at kanna, at tað ger tað, sum varð biðið um, áðrenn tú góðkennir tað.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Stytting fyri enska quality assurance, góðskutrygging: tey sjálvvirkandi eftirlitini, sum koyra, áðrenn nakað fer live. Tá ið QA er reytt, er okkurt miseydnað, og tað kann ikki fara live, fyrr enn tað er rættað.","also":["góðskueftirlit","góðskutrygging","quality assurance"]},{"id":"deploy","g":"change","word":"Deploy","text":"At seta eina nýggja útgávu í loftið, til dømis á ein ambætara, har fólk brúka hana."},{"id":"release","g":"change","word":"Útgáva","text":"Ein navngivin bólkur av lidnum arbeiði, sum fer live saman, við stuttum notum um, hvat er broytt. 🚀 Útgávur skrivar notarnar út frá teimum lidnu kortunum.","also":["útgávur","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"At fara aftur til seinastu útgávuna, sum virkaði, tá ið ein nýggj elvir til trupulleikar. Í AI-gile ger tað ein kekklista við teimum angra-stigunum, ið eru skrivað á hvørja broyting.","also":["rulla aftur","rullað aftur","fara aftur"]},{"id":"live","g":"change","word":"Live","text":"Tann veruliga útgávan, sum fólk nýta, ímóti einum avriti at royna ting á. Menningarfólk kalla tað eisini production.","also":["framleiðsla","production","í gongd"],"noTip":1},{"id":"change","g":"change","word":"Broyting","text":"Ein ætlað broyting í nøkrum, sum fólk líta á, skrivað niður fyrst: hvat, hví, váðin, nær og hvussu hon verður angrað. Byrja eina við 🔀 Bið um broyting.","also":["broytingar","broytingarumbøn","broytingarumbønir"],"noTip":1},{"id":"risk","g":"change","word":"Váði","text":"Okkurt, sum kann fara skeivt, givið stig eftir, hvussu sannlíkt og hvussu ringt tað hevði verið. ⚠️ Váðar goymir teir í einum lista, hægstu stig fyrst, hvør við einum degi at hyggja aftur.","also":["váðar","váðaskrá"]},{"id":"chgwin","g":"change","word":"Broytingargluggi","text":"Tíðirnar, tá ið broytingar sleppa at fara live, til dømis eitt kvirt týsdagskvøld. Uttan fyri ein glugga kann eitt broytingarkort ikki verða liðugt, uttan so at tað er ein neyðstøða.","also":["broytingargluggar"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"Ein skjót atkvøðugreiðsla beint áðrenn ein broyting fer live: hvør, sum skal góðkenna, sigur Go ella No go. Tað fer bara víðari, tá ið tey eru samd.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Góðkenning","text":"At bíða eftir einum ja, áðrenn arbeiðið byrjar. Eitt kort, sum ein vinur stovnar, ella ein broyting, bíðar í ✅ Góðkenningar, til tú góðkennir ella avvísir tað.","also":["góðkenningar"]},{"id":"quiettime","g":"change","word":"Kvirr tíð","text":"Eitt tíðarskeið, sum eitt stream, ein framsýning ella náttin, tá ið einki fer live. Toymini halda fram at arbeiða og royna, men at fara live bíðar, til tað er av. Aðrastaðni verður tað kallað change freeze.","also":["kvirrar tíðir","broytingarstøðgur","change freeze"]},{"id":"service","g":"run","word":"Tænasta","text":"Okkurt, tú hevur bygt, sum fólk líta á, eitt nú ein heimasíða ella ein app, sum verður ansað eftir, so tað heldur fram at virka. Set kross við „Henda verkætlan er ein tænasta“ og sig, hvat hon bjóðar, hvør nýtir hana, og hvør hevur vakt.","also":["tænastur","tænastu"]},{"id":"uptime","g":"run","word":"Uppi-tíðar eftirlit","text":"Eitt sjálvvirkandi eftirlit, hvørjar fáar minuttir, at tín tænasta enn svarar. Miseydnast tað fleiri ferðir á rað, letur AI-gile sjálvt eitt hendingarkort upp.","also":["uppi-tíð","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Støðusíða","text":"Ein almenn síða, sum vísir, um ein tænasta virkar (grønt, appelsingult ella reytt), við nýggjastu dagføringini, so tey, ið nýta hana, kunnu hyggja í staðin fyri at spyrja.","also":["støðusíður","støðusíðuni","status page"]},{"id":"desk","g":"run","word":"Tænastuskrivborð","text":"Har spurningar og fráboðanir frá teimum, sum brúka tænastuna hjá tær, koma inn. AI-gile flokkar hvørja sum umbøn, hending ella hugskot og sigur frá, tá ið hon líkist okkurt, sum longu er fráboðað.","also":["tænastuskrivborð","skrivborð","service desk","hjálparskrivborð"]},{"id":"svcrequest","g":"run","word":"Tænastuumbøn","text":"Onkur biður um okkurt vanligt, t.d. eina nýggja kontu ella eina lítla hjálp, heldur enn at boða frá, at okkurt er í stykkjum. Hon bíðar eftir sínari tørn; ein hending fer fram um.","also":["tænastuumbønir"]},{"id":"incident","g":"run","word":"Hending","text":"Okkurt, sum er í stykkjum fyri tey, ið nýta tað, júst nú, eitt nú tá ið heimasíðan er niðri. Eitt 🔥 hendingarkort fer fram um røðina: at fáa tað at virka aftur kemur fyrst.","also":["hendingar","hendingin","incident"]},{"id":"major","g":"run","word":"Stór hending","text":"Ein stór hending: nógv fólk rakt, ella pengar ella dátur í vanda. Ein knøttur setir øll toymi á hana (sverm), vekir tann, ið hevur vakt, og biður um eina støðudagføring hvønn 30. minutt.","also":["stórar hendingar","major incident"]},{"id":"oncall","g":"run","word":"Vakt","text":"At vera tann, sum svarar, tá ið okkurt fer í stykkir, eisini um náttina. Hvør tænasta hevur ein toymislim á vakt, sum verður vaktur fyrst við hennara hendingum.","also":["á vakt","vaktin","on-call","on call"]},{"id":"replyby","g":"run","word":"Svartíð","text":"Hvussu leingi eitt kort má bíða eftir fyrsta svari, til dømis ein tíma fyri eina hending. Eftir tað fær tað eitt reytt ur, so einki verður gloymt í kvirrum. Verður eisini kallað svarmál.","also":["svartíðir","svarmál"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Ein stutt eftirmeting eftir eina hending: hvat hendi, hvat hjálpti, og hvat skal broytast, uttan at geva nøkrum skyldina. Ein hending kann ikki verða latin aftur uttan hana.","also":["post-mortems","postmortem","eftirmeting"]},{"id":"problem","g":"run","word":"Trupulleiki","text":"Tann fjalda orsøkin aftan fyri eina ella fleiri hendingar. Eitt 🧩 trupulleikakort savnar hendingar, sum koma aftur og aftur, so orsøkin verður funnin og rættað fyri alla tíð.","also":["trupulleikar","trupulleikin"],"noTip":1},{"id":"rootcause","g":"run","word":"Rótarorsøk","text":"Tann veruliga orsøkin til, at okkurt fór í stykkir, ikki bara tað, tú sást fara skeivt. Rætta rótarorsøkina, og hendingin kemur ikki aftur.","also":["rótarorsøkir","grundarsøk"]},{"id":"workaround","g":"run","word":"Bráðabirgdaloysn","text":"Ein háttur at halda tingunum koyrandi, til tann veruliga rættingin er klár, eitt nú at endurbyrja okkurt, tá ið tað steðgar. Hon er skrivað á trupulleikakortið, so eingin skal finna út av henni aftur.","also":["bráðabirgdaloysnir","neyðloysn","workaround"]},{"id":"knownerror","g":"run","word":"Kendur feilur","text":"Ein trupulleiki, har orsøkin er skild, og sum hevur eina bráðabirgdaloysn, men sum enn ikki er rættaður. 🧩 Kendir feilir listar teir upp, so øll nýta bráðabirgdaloysnina í staðin fyri at grava aftur.","also":["kendir feilir","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Stig fyri stig vegleiðing at rætta ein kendan slag av trupulleika, so tað verður gjørt á sama hátt, skjótt, hvørja ferð. Eftir eina stóra hending kann toymið skjóta upp eina, sum tú góðkennir.","also":["runbooks","rakstrarvegleiðing"]},{"id":"ci","g":"run","word":"Konfiguratiónsting","text":"Eitt ting, sum tænastan hjá tær byggir á, t.d. ein ambætari, eitt domeni, eitt sertifikat, ein lykil ella ein veitari. 🗂️ Konfiguratiónsting vísir tey fyri hvørja tænastu, so tú sært, hvat ein hending ávirkar, og hvat skal endurnýggjast ella afturgoymast.","also":["konfiguratiónstingini","konfiguratiónsting","CI"]},{"id":"expiry","g":"run","word":"Útgangsdagur","text":"AI-gile hevur eyga við dagfestingum, t.d. nær eitt sertifikat ella eitt domeni gongur út. Innan 30 dagar áðrenn dagfestingina ger tað eitt kort til at endurnýggja tað, so einki steðgar óvænta.","also":["útgangsdagar","útgongd","eftirlit við útgongd"]},{"id":"backup","g":"run","word":"Trygdaravrit","text":"Eitt goymt avrit av tínum dátum frá áður, at falla aftur á, um okkurt fer burt ella verður skatt. AI-gile ger eitt trygdaravrit av tínum borðum hvønn dag.","also":["trygdaravritið","backup","backups"]},{"id":"restore","g":"run","word":"Endurskapan","text":"At seta dátur aftur úr einum trygdaravriti. Eitt trygdaravrit telur bara veruliga, tá ið tú veitst, at tað kann endurskapast, so tað loysir seg at royna tað nú og tá.","also":["endurskapa","endurskapað","restore"]},{"id":"svcreview","g":"run","word":"Tænastukanning","text":"Eitt afturlit á ein mánað hjá eini tænastu: hendingar, sum vórðu latnar upp og rættaðar, hvussu skjótt fólk fingu svar, uppitíð og brúkt tokens. Mánaðarlig kanning vísir tað fyri hvørja tænastu.","also":["tænastukanningar","mánaðarlig kanning","mánaðarligar kanningar"]},{"id":"accessreview","g":"run","word":"Atgongdarkanning","text":"At kanna hvønn 90. dag, hvør enn sleppur inn: deilileinkjur, leiklutir hjá vinum og goymd loyndarmál. Tú goymir ella strikar hvørt, so gomul atgongd ikki verður liggjandi.","also":["atgongdarkanningar"]},{"id":"improvements","g":"run","word":"Betringarlisti","text":"Alt, sum toymið hevur avgjørt at gerast betri til, á einum stað: retro-uppskot, kanningarhandlingar og trupulleikarættingar, hvørt við sínari støðu. Tú finnur tað undir 📈 Betringar.","also":["betringarlistar","betringar"]},{"id":"tokencap","g":"run","word":"Token-tak","text":"Eitt mánaðarligt mark fyri, hvussu nógv tokens agentarnir hjá eini tænastu sleppa at brúka. Við 80% fært tú eina ávaring; við 100% bíðar bakgrundsarbeiðið hjá teimum til næsta mánað, ella til tú hækkar takið.","also":["token-tøk","mánaðarligt token-tak"]},{"id":"backlog","g":"team","word":"Backlog","text":"Hugskot og arbeiði, sum ikki er ætlað enn. Einki verður gjørt við tað, fyrr enn tað fer til At gera."},{"id":"sprint","g":"team","word":"Sprint","text":"Ein stuttur tíðarbolkur av arbeiði (ofta ein ella tvær vikur) við einum avtalaðum sett av kortum at gera liðug.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Ein skjót innrokning: hvat hvør toymislimur gjørdi, hvat hann ger næst, og hvat steðgar honum.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Eitt borð við súlum (At gera, Í gerð, Liðugt), har kort flyta seg frá vinstru til høgru, sum arbeiðið gongur."},{"id":"wip","g":"team","word":"WIP-mark","text":"Work in progress: flest kort, ein súla skal hava, so at toymið ger ting liðug, áðrenn tað byrjar fleiri.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"Stutti kekklisti toymisins um, hvat „liðugt“ merkir, eitt nú roynt og greitt frá, áðrenn eitt kort verður latið tær. Tvíburin, Definition of Ready, sigur, nær eitt kort er nóg greitt at byrja uppá.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Royndabunki","text":"Tey lidnu kortini, sum bíða eftir, at tú roynir tey, eitt eftir annað. Góðtak eitt ella send tað aftur við eini notu, og tað næsta kemur fram.","also":["royndabunkar","royndabunka"]},{"id":"retro","g":"team","word":"Retro","text":"Eitt afturlit á, hvussu toymið arbeiðir, fyri at semjast um eitt ting at gera betur. Í AI-gile skjýtur ein retro upp eina broyting í arbeiðshættum toymisins, og tú sigur Go ella Ikki enn.","also":["retrospektiv","afturlit"]},{"id":"peerreview","g":"team","word":"Peer review","text":"Eitt annað par av eygum: ein onnur AI kannar arbeiðið á hvørjum korti, áðrenn tað kemur til tín, so færri mistøk sleppa ígjøgnum.","also":["code review","kodukanning"]},{"id":"swarm","g":"team","word":"Sverm","text":"Allar hendur til arbeiðis: hvørt toymi leggur annað arbeiði frá sær fyri at hjálpa við eini skundandi verkætlan, til hon er loyst. Aðrar verkætlanir bíða so leingi.","also":["sværm","swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Tann, sum heldur arbeiðinum gangandi: varnast kort, ið sita føst, eggjar toymunum og minnir teg á, hvat bíðar. Í AI-gile ger Lead Scrum Master hetta tvørtur um allar verkætlanir.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Ein AI, sum arbeiðir sjálvt við eini uppgávu: lesur koduna, ger broytingar, koyrir kanningar og boðar frá.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Eindin, sum AI-nýtsla verður tald í: umleið nøkur bókstavir av tekstið lisin ella skrivaður. Færri tokens, meira eftir av tíni ætlan.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Ein lítil skipan, sum koyrir av sær sjálvari á einum ásettum eyguablikki, t.d. tá ein AI-seta byrjar, so at toymið hoyrir tínar viðmerkingar.","also":["hooks"]}]}};
